import React from 'react';
import { Score } from '../types';
import { Link } from 'react-router-dom';
import { EXAMPLE_FOOTBALL_TEAMS, EXAMPLE_BASKETBALL_TEAMS } from '../constants';

interface ScoreCardProps {
  score: Score;
}

const getTeamPageLink = (teamName: string, sport: string) => {
  // Simple heuristic for linking to team pages based on example data
  if (sport === 'Football' && EXAMPLE_FOOTBALL_TEAMS.includes(teamName)) {
    return `/team/${encodeURIComponent(teamName)}`;
  }
  if (sport === 'Basketball' && EXAMPLE_BASKETBALL_TEAMS.includes(teamName)) {
    return `/team/${encodeURIComponent(teamName)}`;
  }
  return '#'; // Fallback if no specific team page can be generated
};

export const ScoreCard: React.FC<ScoreCardProps> = ({ score }) => {
  const isLive = score.gameState === 'Live';
  const isFinished = score.gameState === 'Fulltime';

  return (
    <div className="bg-gray-800 rounded-lg shadow-lg p-4 mb-4 transform hover:scale-102 transition-all duration-300 ease-in-out cursor-pointer">
      <div className="flex justify-between items-start text-xs text-gray-400 mb-2">
        <span className="font-semibold text-emerald-400 uppercase">{score.sport}</span>
        <span className="font-medium">{score.league}</span>
      </div>

      <div className="flex items-center justify-between text-lg md:text-xl font-bold mb-3">
        {/* Home Team */}
        <Link to={getTeamPageLink(score.homeTeam, score.sport)} className="flex items-center flex-grow min-w-0 pr-2">
          <img
            src={`https://picsum.photos/30/30?random=${score.homeTeam.charCodeAt(0)}`}
            alt={`${score.homeTeam} logo`}
            className="w-6 h-6 rounded-full mr-2 hidden sm:block"
          />
          <span className="truncate hover:underline">{score.homeTeam}</span>
        </Link>
        <span className="mx-2 text-2xl font-extrabold text-emerald-200">{score.homeScore}</span>
      </div>

      <div className="flex items-center justify-between text-lg md:text-xl font-bold mb-3">
        {/* Away Team */}
        <Link to={getTeamPageLink(score.awayTeam, score.sport)} className="flex items-center flex-grow min-w-0 pr-2">
          <img
            src={`https://picsum.photos/30/30?random=${score.awayTeam.charCodeAt(0)}`}
            alt={`${score.awayTeam} logo`}
            className="w-6 h-6 rounded-full mr-2 hidden sm:block"
          />
          <span className="truncate hover:underline">{score.awayTeam}</span>
        </Link>
        <span className="mx-2 text-2xl font-extrabold text-emerald-200">{score.awayScore}</span>
      </div>

      <div className="flex justify-between items-center mt-4 pt-3 border-t border-gray-700 text-sm font-medium">
        <span className={`px-2 py-1 rounded-full ${isLive ? 'bg-red-600 text-white' : isFinished ? 'bg-green-600 text-white' : 'bg-gray-600 text-gray-200'}`}>
          {score.gameState}
        </span>
        <span className="text-gray-300">{score.gameTime}</span>
      </div>
    </div>
  );
};

import React, { useEffect, useRef } from 'react';
import { PlayerProfile } from '../types';
import Plotly from 'plotly.js-dist';
import { Link } from 'react-router-dom';

interface PlayerDetailProps {
  player: PlayerProfile;
}

export const PlayerDetail: React.FC<PlayerDetailProps> = ({ player }) => {
  const chartRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (player && chartRef.current) {
      const seasons = player.stats.map(s => s.season);
      const points = player.stats.map(s => s.pointsPerGame);
      const assists = player.stats.map(s => s.assistsPerGame);
      const rebounds = player.stats.map(s => s.reboundsPerGame);

      const data: Plotly.Data[] = [
        {
          x: seasons,
          y: points,
          name: 'Points Per Game',
          type: 'bar',
          marker: { color: '#047857' }, // emerald-600
        },
        {
          x: seasons,
          y: assists,
          name: 'Assists Per Game',
          type: 'bar',
          marker: { color: '#34d399' }, // emerald-400
        },
        {
          x: seasons,
          y: rebounds,
          name: 'Rebounds Per Game',
          type: 'bar',
          marker: { color: '#a7f3d0' }, // emerald-200
        },
      ];

      const layout: Partial<Plotly.Layout> = {
        title: {
          text: `${player.name} Seasonal Averages`,
          font: {
            color: '#e0f2f7', // text-gray-50
          },
        },
        xaxis: {
          title: 'Season',
          automargin: true,
          tickfont: {
            color: '#9ca3af', // text-gray-400
          },
          titlefont: {
            color: '#e0f2f7',
          },
          gridcolor: '#4b5563', // gray-600
          linecolor: '#4b5563',
        },
        yaxis: {
          title: 'Average per Game',
          automargin: true,
          tickfont: {
            color: '#9ca3af',
          },
          titlefont: {
            color: '#e0f2f7',
          },
          gridcolor: '#4b5563',
          linecolor: '#4b5563',
        },
        barmode: 'group',
        plot_bgcolor: '#1f2937', // gray-800
        paper_bgcolor: '#1f2937', // gray-800
        legend: {
          font: {
            color: '#e0f2f7',
          },
          bgcolor: 'rgba(0,0,0,0)',
        },
        margin: {
          l: 50,
          r: 50,
          b: 50,
          t: 70,
          pad: 4
        },
        responsive: true,
      };

      Plotly.newPlot(chartRef.current, data, layout, { responsive: true });
    }

    return () => {
      if (chartRef.current) {
        Plotly.purge(chartRef.current);
      }
    };
  }, [player]);

  return (
    <div className="bg-gray-800 rounded-lg shadow-xl p-6 md:p-8">
      <div className="flex flex-col md:flex-row items-center md:items-start md:space-x-8 mb-8">
        <img
          src={player.imageUrl || `https://picsum.photos/200/200?random=${player.id}`}
          alt={`${player.name}`}
          className="w-48 h-48 object-cover rounded-full border-4 border-emerald-500 mb-6 md:mb-0 shadow-md"
        />
        <div className="text-center md:text-left flex-grow">
          <h1 className="text-4xl font-extrabold text-emerald-400 mb-2">{player.name}</h1>
          <p className="text-xl text-gray-300 mb-4">
            <Link to={`/team/${encodeURIComponent(player.team)}`} className="hover:underline text-emerald-300">
              {player.team}
            </Link>
            {' '}• {player.sport} • {player.position}
          </p>
          <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 text-gray-400 mb-6">
            <div>
              <span className="block font-semibold">Age:</span>
              <span className="text-lg">{player.age}</span>
            </div>
            <div>
              <span className="block font-semibold">Nationality:</span>
              <span className="text-lg">{player.nationality}</span>
            </div>
