import { useUser } from '../context/UserContext';
import { ScoreCard } from '../components/ScoreCard'; // Reusing ScoreCard

interface FollowedGameData {
  score: Score;
  odds?: Odds;
  status: QueryStatus;
  error: string | null;
}

// Helper to format odds for display
const formatOdds = (odds?: Odds) => {
  if (!odds) return 'Odds N/A';
  return (
    <div className="text-xs text-gray-400 mt-1 space-y-0.5">
      <p>O/U: <span className="text-emerald-300 font-semibold">{odds.overUnder}</span></p>
      <p>Spread: {odds.spread > 0 ? '+' : ''}<span className="text-blue-300 font-semibold">{odds.spread}</span></p>
      <p>ML Home: <span className="text-yellow-300 font-semibold">{odds.moneylineHome > 0 ? '+' : ''}{odds.moneylineHome}</span></p>
      <p>ML Away: <span className="text-yellow-300 font-semibold">{odds.moneylineAway > 0 ? '+' : ''}{odds.moneylineAway}</span></p>
      {odds.moneylineDraw && <p>ML Draw: <span className="text-yellow-300 font-semibold">{odds.moneylineDraw > 0 ? '+' : ''}{odds.moneylineDraw}</span></p>}
      <p className="text-gray-500 text-[10px]">Updated: {new Date(odds.lastUpdated).toLocaleTimeString()}</p>
    </div>
  );
};

interface FollowedGameCardProps {
  gameData: FollowedGameData;
  onRemove: (gameId: string) => void;
  isLoading: boolean;
}

const FollowedGameCard: React.FC<FollowedGameCardProps> = ({ gameData, onRemove, isLoading }) => {
  if (isLoading) {
    return <ScoreCard loading={true} />; // Use existing skeleton for loading
  }

  const { score, odds, error } = gameData;

  return (
    <div className="bg-gray-800 rounded-lg shadow-lg p-4 mb-4 flex flex-col justify-between h-full">
      {error ? (
        <div className="flex flex-col items-center justify-center h-full text-red-400 text-center">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-8 w-8 mb-2" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
          </svg>
          <p className="text-sm">{error}</p>
          <button onClick={() => onRemove(score.gameId || '')} className="mt-2 text-xs text-red-500 hover:underline">
            Remove
          </button>
        </div>
      ) : (
        <>
          <ScoreCard score={score} />
          <div className="mt-4 pt-4 border-t border-gray-700 flex justify-between items-end">
            <div>
              <h3 className="text-lg font-semibold text-emerald-300 mb-1">Odds:</h3>
              {formatOdds(odds)}
            </div>
            <button
              onClick={() => onRemove(score.gameId || '')}
              aria-label={`Remove ${score.homeTeam} vs ${score.awayTeam} from scoreboard`}
              className="p-2 rounded-full hover:bg-red-700 text-red-400 hover:text-white transition-colors self-end"
            >
              <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                <path strokeLinecap="round" strokeLinejoin="round" d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16" />
              </svg>
            </button>
          </div>
        </>
      )}
    </div>
  );
};


export const MyScoreboardPage: React.FC = () => {
  const { currentUser } = useUser();
  const [followedGames, setFollowedGames] = useState<Record<string, FollowedGameData>>({});
  const [overallStatus, setOverallStatus] = useState<QueryStatus>('idle');

  const fetchFollowedGameData = useCallback(async () => {
    setOverallStatus('loading');
    const gameIds = getFollowedGames(currentUser.id);
    if (gameIds.length === 0) {
      setFollowedGames({});
      setOverallStatus('success');
      return;
    }

    const fetchedData: Record<string, FollowedGameData> = {};
    let hasErrors = false;

    for (const gameId of gameIds) {
      fetchedData[gameId] = { score: {}, odds: undefined, status: 'loading', error: null }; // Initialize loading state
      try {
        // Fetch score (mocked to potentially provide specific game details if gameId is hint)
        const scores = await geminiService.getLiveScores(undefined, undefined, undefined, gameId);
        const score = scores.find(s => s.gameId === gameId); // Find the relevant game

        if (!score) {
          throw new Error(`Game details not found for ID: ${gameId}`);
        }

        // Fetch odds
        const odds = await geminiService.getGameOdds(gameId, score.homeTeam || 'Home Team', score.awayTeam || 'Away Team');

        fetchedData[gameId] = {
          score,
          odds,
          status: 'success',
          error: null,
        };
      } catch (err: any) {
        console.error(`Failed to fetch data for followed game ${gameId}:`, err);
        hasErrors = true;
        fetchedData[gameId] = {
          score: { gameId }, // Keep gameId for removal, even if other details failed
          odds: undefined,
          status: 'error',
          error: err.message || `Failed to load data for game ${gameId}`,
        };
      }
    }
    setFollowedGames(fetchedData);
    setOverallStatus(hasErrors ? 'error' : 'success');
  }, [currentUser.id]);

  useEffect(() => {
    fetchFollowedGameData();
  }, [fetchFollowedGameData]);

  const handleRemoveGame = (gameId: string) => {
    removeFollowedGame(currentUser.id, gameId);
    setFollowedGames(prev => {
      const newState = { ...prev };
      delete newState[gameId];
      return newState;
    });
  };

  const gameIds = Object.keys(followedGames);
  const isLoading = overallStatus === 'loading';
  const noFollowedGames = !isLoading && gameIds.length === 0;

  return (
    <div className="p-4">
      <h1 className="text-4xl font-extrabold text-center text-emerald-400 mb-8">My Scoreboard</h1>

      {isLoading && gameIds.length === 0 && <LoadingSpinner />}
      {noFollowedGames && (
        <p className="text-center text-gray-400 text-xl py-10">
          You aren't following any games yet.
          <br />
          Ask the chatbot about a game and add it to your scoreboard!
        </p>
      )}

      {gameIds.length > 0 && (
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {gameIds.map(gameId => (
            <FollowedGameCard
              key={gameId}
              gameData={followedGames[gameId]}
              onRemove={handleRemoveGame}
              isLoading={followedGames[gameId]?.status === 'loading'}
            />
          ))}
        </div>
      )}

      <div className="mt-10 p-6 bg-gray-800 rounded-lg shadow-xl text-center">
        <h2 className="text-2xl font-bold text-emerald-300 mb-4">Parlays & Betting Lines</h2>
        <p className="text-gray-300 mb-4">
          The individual game odds are displayed above. For combining multiple bets (parlays) and more advanced lines,
          please refer to a dedicated sports betting platform. URScoreCard aims to provide score and odds information,
          but does not facilitate betting directly.
        </p>
        <p className="text-sm text-gray-500">
          This feature is for informational purposes only. Betting involves risk. Please bet responsibly.
        </p>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Score } from '../types';
import { Link } from 'react-router-dom';
import { EXAMPLE_FOOTBALL_TEAMS, EXAMPLE_BASKETBALL_TEAMS } from '../constants';
import { useUser } from '../context/UserContext';
import { addFavoriteTeam, removeFavoriteTeam, isFavoriteTeam } from '../utils/favorites';


interface ScoreCardProps {
  score?: Score; // Make score optional for loading state
  loading?: boolean; // New prop for loading state
}

const getTeamPageLink = (teamName: string, sport: string) => {
  // Simple heuristic for linking to team pages based on example data
  if (sport === 'Football' && EXAMPLE_FOOTBALL_TEAMS.includes(teamName)) {
    return `/team/${encodeURIComponent(teamName)}`;
  }
  if (sport === 'Basketball' && EXAMPLE_BASKETBALL_TEAMS.includes(teamName)) {
    return `/team/${encodeURIComponent(teamName)}`;
  }
  return '#'; // Fallback if no specific team page can be generated
};

export const ScoreCard: React.FC<ScoreCardProps> = ({ score, loading }) => {
  const { currentUser } = useUser();
  const [isHomeTeamFavorited, setIsHomeTeamFavorited] = useState(false);
  const [isAwayTeamFavorited, setIsAwayTeamFavorited] = useState(false);

  useEffect(() => {
    if (score?.homeTeam) {
      setIsHomeTeamFavorited(isFavoriteTeam(currentUser.id, score.homeTeam));
    }
    if (score?.awayTeam) {
      setIsAwayTeamFavorited(isFavoriteTeam(currentUser.id, score.awayTeam));
    }
  }, [score, currentUser.id]);

  const handleToggleHomeTeamFavorite = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent navigation when clicking the star
    if (!score?.homeTeam) return;

    if (isHomeTeamFavorited) {
      removeFavoriteTeam(currentUser.id, score.homeTeam);
    } else {
      addFavoriteTeam(currentUser.id, score.homeTeam);
    }
    setIsHomeTeamFavorited(prev => !prev);
  };

  const handleToggleAwayTeamFavorite = (e: React.MouseEvent) => {
    e.stopPropagation(); // Prevent navigation when clicking the star
    if (!score?.awayTeam) return;

    if (isAwayTeamFavorited) {
      removeFavoriteTeam(currentUser.id, score.awayTeam);
    } else {
      addFavoriteTeam(currentUser.id, score.awayTeam);
    }
    setIsAwayTeamFavorited(prev => !prev);
  };

  if (loading) {
    return (
      <div className="bg-gray-800 rounded-lg shadow-lg p-4 mb-4 animate-pulse">
        {/* Header Skeleton */}
        <div className="flex justify-between items-start text-xs text-gray-400 mb-2">
          <div className="h-4 bg-gray-700 rounded w-1/4"></div>
          <div className="h-4 bg-gray-700 rounded w-1/6"></div>
        </div>

        {/* Home Team Skeleton */}
        <div className="flex items-center justify-between text-lg md:text-xl font-bold mb-3">
          <div className="flex items-center flex-grow min-w-0 pr-2">
            <div className="w-8 h-8 rounded-full bg-gray-700 mr-3 flex-shrink-0"></div>
            <div className="h-6 bg-gray-700 rounded w-3/5"></div>
          </div>
          <div className="h-8 bg-gray-700 rounded w-1/12 mx-2"></div>
        </div>

        {/* Away Team Skeleton */}
        <div className="flex items-center justify-between text-lg md:text-xl font-bold mb-3">
          <div className="flex items-center flex-grow min-w-0 pr-2">
            <div className="w-8 h-8 rounded-full bg-gray-700 mr-3 flex-shrink-0"></div>
            <div className="h-6 bg-gray-700 rounded w-3/5"></div>
          </div>
          <div className="h-8 bg-gray-700 rounded w-1/12 mx-2"></div>
        </div>

        {/* Footer Skeleton */}
        <div className="flex justify-between items-center mt-4 pt-3 border-t border-gray-700 text-sm font-medium">
          <div className="h-6 bg-gray-700 rounded-full w-1/5"></div>
          <div className="h-6 bg-gray-700 rounded w-1/4"></div>
        </div>
      </div>
    );
  }

  // If not loading and score is undefined, return null or a placeholder if desired
  if (!score) {
    return null; // Or <ErrorDisplay message="Score data not available" />
  }

  const isLive = score.gameState === 'Live';
  const isFinished = score.gameState === 'Fulltime';
  const isUpcoming = score.gameState === 'Upcoming';

  return (
    <div className="bg-gray-800 rounded-lg shadow-lg p-4 mb-4 transform hover:scale-102 transition-all duration-300 ease-in-out cursor-pointer">
      <div className="flex justify-between items-start text-xs text-gray-400 mb-2">
        <span className="font-semibold text-emerald-400 uppercase">{score.sport}</span>
        <span className="font-medium">{score.league}</span>
      </div>

      <div className="flex items-center justify-between text-lg md:text-xl font-bold mb-3">
        {/* Home Team */}
        <Link to={getTeamPageLink(score.homeTeam, score.sport)} className="flex items-center flex-grow min-w-0 pr-2 group">
          <img
            src={`https://picsum.photos/seed/${encodeURIComponent(score.homeTeam)}/30/30`}
            alt={`${score.homeTeam} logo`}
            className="w-8 h-8 rounded-full mr-3 border border-gray-600 bg-gray-900 flex-shrink-0"
          />
          <span className="truncate text-gray-100 group-hover:underline" title={score.homeTeam}>{score.homeTeam}</span>
        </Link>
        <button
          onClick={handleToggleHomeTeamFavorite}
          aria-label={isHomeTeamFavorited ? "Remove home team from favorites" : "Add home team to favorites"}
          className="p-1 rounded-full hover:bg-gray-700 transition-colors flex-shrink-0"
        >
          <svg
            xmlns="http://www.w3.org/2000/svg"
            className={`h-5 w-5 ${isHomeTeamFavorited ? 'text-yellow-400 fill-current' : 'text-gray-400'}`}
            viewBox="0 0 20 20"
            fill="currentColor"
          >
            <path d="M9.049 2.927c.3-.921 1.603-.921 1.902 0l1.07 3.292a1 1 0 00.95.69h3.462c.969 0 1.371 1.24.588 1.81l-2.817 2.033a1 1 0 00-.364 1.118l1.07 3.292c.3.921-.755 1.688-1.54 1.118l-2.817-2.033a1 1 0 00-1.175 0l-2.817 2.033c-.784.57-1.838-.197-1.539-1.118l1.07-3.292a1 1 0 00-.364-1.118L2.98 8.72c-.783-.57-.38-1.81.588-1.81h3.461a1 1 0 00.951-.69l1.07-3.292z" />
          </svg>
