      const rebounds = player.stats.map(s => s.reboundsPerGame);

      const data: Plotly.Data[] = [
        {
          x: seasons,
          y: points,
          name: 'Points Per Game',
          type: 'bar',
          marker: { color: 'var(--color-text-accent)' },
        },
        {
          x: seasons,
          y: assists,
          name: 'Assists Per Game',
          type: 'bar',
