  if (sport === 'Football' && EXAMPLE_FOOTBALL_PLAYERS.includes(playerName)) {
    return `/player/${encodeURIComponent(playerName)}`;
  }
  if (sport === 'Basketball' && EXAMPLE_BASKETBALL_PLAYERS.includes(playerName)) {
    return `/player/${encodeURIComponent(playerName)}`;
  }
  return '#';
};

