import React, { useState, useEffect, useCallback } from 'react';
import { ScoreCard } from '../components/ScoreCard';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { ErrorDisplay } from '../components/ErrorDisplay';
import { geminiService } from '../services/geminiService';
import { Score, Sport, QueryStatus } from '../types';
import { useSearchParams } from 'react-router-dom';

export const HomePage: React.FC = () => {
  const [scores, setScores] = useState<Score[]>([]);
  const [status, setStatus] = useState<QueryStatus>('idle');
  const [error, setError] = useState<string | null>(null);
  const [searchParams] = useSearchParams();

  // Get the sport from the URL, default to 'All' if not present
  const urlSport = searchParams.get('sport');
  const selectedSport = (urlSport || 'All') as Sport | 'All';

  const fetchScores = useCallback(async (sport?: Sport) => {
    setStatus('loading');
    setError(null);
    try {
      const fetchedScores = await geminiService.getLiveScores(sport);
      setScores(fetchedScores);
      setStatus('success');
    } catch (err) {
      console.error("Failed to fetch scores:", err);
      setError("Failed to load scores. Please try again later.");
      setStatus('error');
    }
  }, []);

  useEffect(() => {
    fetchScores(selectedSport === 'All' ? undefined : selectedSport);
  }, [selectedSport, fetchScores]);

  const handleRetry = () => {
    fetchScores(selectedSport === 'All' ? undefined : selectedSport);
  };

  // Group scores by date for better readability
  const groupedScores = scores.reduce((acc, score) => {
    const date = score.date || 'Unknown Date';
    if (!acc[date]) {
      acc[date] = [];
    }
    acc[date].push(score);
    return acc;
  }, {} as Record<string, Score[]>);

  const sortedDates = Object.keys(groupedScores).sort((a, b) => new Date(a).getTime() - new Date(b).getTime());


  return (
    <div className="p-2">
      <h1 className="text-2xl font-extrabold text-center text-accent mb-6">
        {selectedSport === 'All' ? 'Live Scores & Upcoming Games' : `${selectedSport} Scores`}
      </h1>

      {status === 'loading' && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {[...Array(6)].map((_, index) => (
            <ScoreCard key={index} loading={true} />
          ))}
        </div>
      )}
      {status === 'error' && <ErrorDisplay message={error || "Unknown error"} onRetry={handleRetry} />}
      {status === 'success' && scores.length === 0 && (
        <p className="text-center text-secondary text-xl">No scores available for selected sport.</p>
      )}

      {status === 'success' && scores.length > 0 && (
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3">
          {sortedDates.map(date => (
            <React.Fragment key={date}>
              <div className="col-span-full">
                <h2 className="text-lg font-bold text-accent mb-2 border-b border-border pb-1">
                  {date === new Date().toISOString().slice(0, 10) ? 'Today' : date}
                </h2>
              </div>
              {groupedScores[date].map((score) => (
                <ScoreCard key={score.gameId} score={score} />
              ))}
            </React.Fragment>
          ))}
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI, Type, GenerateContentResponse, GroundingChunk, Chat } from "@google/genai";
import { API_KEY, GEMINI_MODEL_TEXT, GEMINI_MODEL_CHAT } from '../constants';
import {
  Score,
  PlayerProfile,
  TeamProfile,
  LeagueProfile,
  SearchResult,
  GroundingLink,
  Odds,
  NewsArticle, // Import new NewsArticle type
} from '../types';

if (!API_KEY) {
  console.warn("API_KEY is not defined. Gemini API calls will fail.");
}

const getGeminiInstance = () => {
  if (!API_KEY) {
    throw new Error("Gemini API Key is not configured.");
  }
  return new GoogleGenAI({ apiKey: API_KEY });
};

async function generateContentWithSchema<T>(
  prompt: string,
  schema: { type: Type; items?: any; properties?: any; propertyOrdering?: string[] }
): Promise<T | undefined> {
  try {
    const ai = getGeminiInstance();
    const response = await ai.models.generateContent({
      model: GEMINI_MODEL_TEXT,
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseMimeType: "application/json",
        responseSchema: schema,
      },
    });

    const jsonStr = response.text?.trim();
    if (!jsonStr) {
      console.error("Gemini response was empty or not text.");
      return undefined;
    }

    // Attempt to parse JSON. Gemini might wrap it in markdown code block.
    let cleanJsonStr = jsonStr;
    if (jsonStr.startsWith("```json") && jsonStr.endsWith("```")) {
      cleanJsonStr = jsonStr.substring(7, jsonStr.length - 3).trim();
    }

    const parsedData: T = JSON.parse(cleanJsonStr);
    return parsedData;

  } catch (error) {
    console.error("Error generating content with schema from Gemini:", error);
    // Attempt to extract more specific error message from the Gemini response structure if available
    if (error instanceof Error) {
      console.error("Gemini API Error:", error.message);
    }
    return undefined;
  }
}

// Helper to extract grounding links
const extractGroundingLinks = (response: GenerateContentResponse): GroundingLink[] => {
  const groundingLinks: GroundingLink[] = [];
  if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
    for (const chunk of response.candidates[0].groundingMetadata.groundingChunks) {
      if (chunk.web?.uri) {
        groundingLinks.push({ uri: chunk.web.uri, title: chunk.web.title });
      }
    }
  }
  return groundingLinks;
};


export const geminiService = {
  getLiveScores: async (sport?: string, teamName?: string, playerName?: string, gameId?: string): Promise<Score[]> => {
    let prompt = `Generate a JSON array of 5-7 live or upcoming sports scores for popular leagues. Ensure a mix of game states (Live, Halftime, Fulltime, Upcoming). Provide realistic team names, scores, and times. Include unique game IDs.`;

    if (sport) {
      prompt += ` Specifically for ${sport}.`;
    }
    if (teamName) {
      prompt += ` Focus on games involving the team "${teamName}".`;
    }
    if (playerName) {
      prompt += ` Focus on games involving the player "${playerName}".`;
    }
    if (gameId) {
      // If a specific gameId is requested, try to ensure at least one score matches
      prompt += ` Ensure at least one game has the ID "${gameId}". If team names are available, ensure that game involves them (e.g., if gameId is for Real Madrid vs Barcelona, make sure that game is present). Also, if the game is live, randomly update its score or game time to simulate real-time changes.`;
    }
    prompt += ` Include the date of the game in YYYY-MM-DD format.`;


    const scoreSchema = {
      type: Type.OBJECT,
      properties: {
        gameId: { type: Type.STRING },
        sport: { type: Type.STRING },
        homeTeam: { type: Type.STRING },
        awayTeam: { type: Type.STRING },
        homeScore: { type: Type.NUMBER },
        awayScore: { type: Type.NUMBER },
        gameState: { type: Type.STRING },
        gameTime: { type: Type.STRING },
        league: { type: Type.STRING },
        date: { type: Type.STRING, description: 'YYYY-MM-DD' },
      },
      required: ['gameId', 'sport', 'homeTeam', 'awayTeam', 'homeScore', 'awayScore', 'gameState', 'gameTime', 'league', 'date'],
      propertyOrdering: ['gameId', 'sport', 'homeTeam', 'awayTeam', 'homeScore', 'awayScore', 'gameState', 'gameTime', 'league', 'date'],
    };

    const arraySchema = {
      type: Type.ARRAY,
      items: scoreSchema,
    };

    const scores = await generateContentWithSchema<Score[]>(prompt, arraySchema);
    return scores || [];
  },

  getNewsArticles: async (entityName: string, category: 'team' | 'player' | 'league' = 'team'): Promise<NewsArticle[]> => {
    const prompt = `Generate a JSON array of 3-5 concise and catchy news headlines and summaries about recent events related to the sports ${category} "${entityName}". Include a plausible source (e.g., ESPN, BBC Sport, The Athletic) and a recent date in 'YYYY-MM-DD' format. Also include a placeholder image URL from 'https://picsum.photos/400/200?random={seed}' where seed is unique.`;

    const newsArticleSchema = {
      type: Type.OBJECT,
      properties: {
        title: { type: Type.STRING },
        summary: { type: Type.STRING },
        source: { type: Type.STRING },
        date: { type: Type.STRING, description: 'YYYY-MM-DD' },
        imageUrl: { type: Type.STRING, description: 'URL for news image' },
      },
      required: ['title', 'summary', 'source', 'date', 'imageUrl'],
      propertyOrdering: ['title', 'summary', 'source', 'date', 'imageUrl'],
    };

    const arraySchema = {
      type: Type.ARRAY,
      items: newsArticleSchema,
    };

    const articles = await generateContentWithSchema<NewsArticle[]>(prompt, arraySchema);
    return articles || [];
  },

  getPlayerProfile: async (playerName: string): Promise<PlayerProfile | undefined> => {
    const prompt = `Generate a detailed JSON profile for a popular sports player named ${playerName}, including their team, sport, position, age, nationality, a short bio, and realistic career statistics (points per game, assists per game, rebounds per game, games played) for the past 3 seasons. Include a placeholder image URL from picsum.photos.`;

    const playerStatSchema = {
