import React, { createContext, useState, useContext, useEffect, ReactNode, useCallback } from 'react';

// Define the shape of the user object
interface User {
  id: string;
  name: string;
}

// Define the shape of the context value
interface UserContextType {
  currentUser: User;
  switchUser: (userId: string) => void;
  availableUsers: User[];
}

// Create the context with a default (undefined) value
const UserContext = createContext<UserContextType | undefined>(undefined);

// Predefined users for testing
const predefinedUsers: User[] = [
  { id: 'user1', name: 'User 1' },
  { id: 'user2', name: 'User 2' },
  { id: 'user3', name: 'User 3' } // Removed trailing comma here
];

interface UserProviderProps {
  children: ReactNode;
}

export const UserProvider: React.FC<UserProviderProps> = ({ children }) => {
  const [currentUser, setCurrentUser] = useState<User>(() => {
    // Initialize from sessionStorage or default to user1
    const storedUserId = sessionStorage.getItem('currentUserId');
    const foundUser = predefinedUsers.find(user => user.id === storedUserId);
    return foundUser || predefinedUsers[0];
  });

  // Persist current user ID to sessionStorage
  useEffect(() => {
    sessionStorage.setItem('currentUserId', currentUser.id);
  }, [currentUser]);

  const switchUser = useCallback((userId: string) => {
    const userToSwitch = predefinedUsers.find(user => user.id === userId);
    if (userToSwitch) {
      setCurrentUser(userToSwitch);
    } else {
      console.warn(`Attempted to switch to unknown user ID: ${userId}`);
    }
  }, []);

  const contextValue = {
    currentUser,
    switchUser,
    availableUsers: predefinedUsers,
  };

  return (
    <UserContext.Provider value={contextValue}>
      {children}
    </UserContext.Provider>
  );
};

// Custom hook to use the UserContext
export const useUser = (): UserContextType => {
  const context = useContext(UserContext);
  if (context === undefined) {
    throw new Error('useUser must be used within a UserProvider');
  }
  return context;
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useUser } from '../context/UserContext';
import { Score, QueryStatus, WatchPartyMessage } from '../types';
import { geminiService } from '../services/geminiService';
import { LoadingSpinner } from '../components/LoadingSpinner';
import { ErrorDisplay } from '../components/ErrorDisplay';
import { getWatchPartyMessages, addWatchPartyMessage } from '../utils/social';

export const WatchPartyPage: React.FC = () => {
  const { gameId } = useParams<{ gameId: string }>();
  const { currentUser, getOtherUsers } = useUser();

  const [game, setGame] = useState<Score | undefined>(undefined);
  const [gameStatus, setGameStatus] = useState<QueryStatus>('idle');
  const [gameError, setGameError] = useState<string | null>(null);

  const [chatMessages, setChatMessages] = useState<WatchPartyMessage[]>([]);
  const [chatInput, setChatInput] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const fetchGameDetails = useCallback(async (id: string) => {
    setGameStatus('loading');
    setGameError(null);
    try {
      const scores = await geminiService.getLiveScores(undefined, undefined, undefined, id);
      const fetchedGame = scores.find(s => s.gameId === id);
      if (fetchedGame) {
        setGame(fetchedGame);
        setGameStatus('success');
      } else {
        setGameError(`Game with ID '${id}' not found.`);
        setGameStatus('error');
      }
    } catch (err) {
      console.error("Failed to fetch game details:", err);
      setGameError("Failed to load game details for the watch party.");
      setGameStatus('error');
    }
  }, []);

  useEffect(() => {
    if (gameId) {
      fetchGameDetails(gameId);
      setChatMessages(getWatchPartyMessages(gameId));
    }
  }, [gameId, fetchGameDetails]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [chatMessages]);

  // AI chat simulation
  useEffect(() => {
    if (!gameId || gameStatus !== 'success' || !game || game.gameState === 'Fulltime') return;

    const interval = setInterval(() => {
      const otherUsers = getOtherUsers(currentUser.id);
      if (otherUsers.length > 0) {
        const randomUser = otherUsers[Math.floor(Math.random() * otherUsers.length)];
        const comments = [
          "What a play!",
          "Did you see that?!",
          "Go team!",
          "Incredible!",
          "This game is intense!",
          "Couldn't ask for a better match.",
          "Wow!",
          "That's how you do it!",
          "What a save!",
          "Unbelievable shot!",
        ];
        const randomComment = comments[Math.floor(Math.random() * comments.length)];

        const aiMessage: WatchPartyMessage = {
          id: Date.now().toString() + Math.random().toString(36).substring(7),
          gameId: gameId,
          senderId: randomUser.id,
          text: randomComment,
          timestamp: new Date(),
        };

        addWatchPartyMessage(aiMessage);
        setChatMessages(prev => [...prev, aiMessage]);
      }
    }, 15000); // Send AI message every 15 seconds

    return () => clearInterval(interval);
  }, [gameId, gameStatus, game, currentUser.id, getOtherUsers]);


  const handleSendChatMessage = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    if (!chatInput.trim() || !gameId) return;

    const newMessage: WatchPartyMessage = {
      id: Date.now().toString(),
      gameId: gameId,
      senderId: currentUser.id,
      text: chatInput,
      timestamp: new Date(),
    };

    addWatchPartyMessage(newMessage);
    setChatMessages(prev => [...prev, newMessage]);
    setChatInput('');
  }, [chatInput, gameId, currentUser.id]);

  if (!gameId) {
    return <ErrorDisplay message="No game ID provided for the watch party." />;
  }

  if (gameStatus === 'loading') {
    return <LoadingSpinner />;
  }

  if (gameStatus === 'error') {
    return <ErrorDisplay message={gameError || "Failed to load game details."} onRetry={() => fetchGameDetails(gameId)} />;
  }

  if (!game) {
    return <ErrorDisplay message="Game details could not be loaded for watch party." />;
  }

  const isLive = game.gameState === 'Live' || game.gameState === 'Halftime';
  const otherUsers = getOtherUsers(currentUser.id);

  return (
    <div className="p-4 bg-secondary rounded-lg shadow-xl flex flex-col lg:flex-row h-[calc(100vh-180px)]">
      {/* Game Info Section */}
      <div className="lg:w-2/3 flex flex-col p-4 border-b lg:border-b-0 lg:border-r border-border mb-4 lg:mb-0 lg:pr-8">
        <h1 className="text-3xl font-extrabold text-accent mb-4">Watch Party: <span className="text-primary">{game.homeTeam} vs {game.awayTeam}</span></h1>

        <div className="bg-tertiary rounded-lg p-4 shadow-md mb-6 flex-shrink-0">
          <div className="flex justify-between items-start text-sm text-secondary mb-2">
            <span className="font-semibold text-accent uppercase">{game.sport}</span>
            <span className="font-medium">{game.league}</span>
          </div>
          <div className="flex items-center justify-between text-lg font-bold mb-1">
            <span className="flex items-center">
              <img src={`https://picsum.photos/seed/${encodeURIComponent(game.homeTeam || '')}/25/25`} alt={`${game.homeTeam} logo`} className="w-6 h-6 rounded-full mr-2" />
              {game.homeTeam}
            </span>
            <span className="text-2xl font-extrabold text-primary">{game.homeScore}</span>
          </div>
          <div className="flex items-center justify-between text-lg font-bold">
            <span className="flex items-center">
              <img src={`https://picsum.photos/seed/${encodeURIComponent(game.awayTeam || '')}/25/25`} alt={`${game.awayTeam} logo`} className="w-6 h-6 rounded-full mr-2" />
              {game.awayTeam}
            </span>
            <span className="text-2xl font-extrabold text-primary">{game.awayScore}</span>
          </div>
          <div className="flex justify-between items-center mt-4 pt-3 border-t border-border text-xs font-medium">
            <span className={`px-2 py-1 rounded-full text-primary font-semibold ${
              isLive ? 'bg-live' : game.gameState === 'Fulltime' ? 'bg-emerald-600' : 'bg-blue-600'
            }`}>
              {game.gameState}
            </span>
            <span className="text-secondary">{game.gameTime}</span>
          </div>
        </div>

        <h2 className="text-xl font-bold text-accent mb-3">Participants</h2>
        <div className="flex flex-wrap gap-2 text-sm text-secondary">
          <span className="flex items-center bg-tertiary px-3 py-1 rounded-full border border-border">
            <img src={`https://picsum.photos/20/20?random=${currentUser.id.charCodeAt(0)}`} alt={`${currentUser.name}'s avatar`} className="w-5 h-5 object-cover rounded-full mr-2" />
            {currentUser.name} (You)
          </span>
          {otherUsers.map(user => (
            <Link to={`/users/${user.id}`} key={user.id} className="flex items-center bg-tertiary px-3 py-1 rounded-full border border-border hover:bg-hover-bg transition-colors">
              <img src={`https://picsum.photos/20/20?random=${user.id.charCodeAt(0)}`} alt={`${user.name}'s avatar`} className="w-5 h-5 object-cover rounded-full mr-2" />
              {user.name}
            </Link>
          ))}
        </div>
      </div>

      {/* Chat Section */}
      <div className="lg:w-1/3 flex flex-col lg:pl-8 h-full">
        <h2 className="text-2xl font-bold text-accent mb-4 border-b border-border pb-2">Live Chat</h2>
        <div className="flex-grow overflow-y-auto custom-scrollbar p-2 mb-4 space-y-3 bg-tertiary rounded-lg">
          {chatMessages.length === 0 ? (
            <p className="text-center text-secondary italic pt-4">No messages yet. Say hello!</p>
          ) : (
            chatMessages.map((msg) => {
              const sender = getOtherUsers(currentUser.id).find(u => u.id === msg.senderId) || currentUser;
              const isCurrentUser = msg.senderId === currentUser.id;
              const senderName = isCurrentUser ? 'You' : sender.name;
              const senderAvatar = `https://picsum.photos/20/20?random=${msg.senderId.charCodeAt(0)}`;

              return (
                <div key={msg.id} className={`flex items-start ${isCurrentUser ? 'justify-end' : 'justify-start'}`}>
                  {!isCurrentUser && (
                    <img src={senderAvatar} alt={`${senderName}'s avatar`} className="w-6 h-6 object-cover rounded-full mr-2 flex-shrink-0 mt-1" />
                  )}
                  <div className={`max-w-[80%] p-2 rounded-lg shadow-sm ${isCurrentUser ? 'bg-accent text-primary' : 'bg-secondary text-primary'}`}>
                    <p className="font-semibold text-xs mb-1">{senderName}</p>
                    <p className="text-sm break-words">{msg.text}</p>
                    <span className="block text-right text-xs text-secondary mt-1">
                      {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                  {isCurrentUser && (
                    <img src={senderAvatar} alt={`${senderName}'s avatar`} className="w-6 h-6 object-cover rounded-full ml-2 flex-shrink-0 mt-1" />
                  )}
                </div>
              );
            })
          )}
          <div ref={messagesEndRef} />
        </div>
        <form onSubmit={handleSendChatMessage} className="flex space-x-2">
          <input
            type="text"
            value={chatInput}
            onChange={(e) => setChatInput(e.target.value)}
            placeholder="Type your message..."
            className="flex-grow bg-tertiary text-primary border border-border rounded-lg py-2 px-3 focus:outline-none focus:ring-1 focus:ring-accent"
            aria-label="Chat message input"
          />
          <button
            type="submit"
            className="bg-accent hover:bg-emerald-700 text-primary p-2 rounded-lg transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
            disabled={!chatInput.trim()}
            aria-label="Send message"
          >
            <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
              <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
            </svg>
          </button>
        </form>
      </div>
    </div>
  );
};

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useParams, Link } from 'react-router-dom';
import { useUser } from '../context/UserContext';
import { getPrivateChatMessages, addPrivateChatMessage } from '../utils/social';
import { PrivateChatMessage } from '../types';

export const IndividualChatPage: React.FC = () => {
  const { otherUserId } = useParams<{ otherUserId: string }>();
  const { currentUser, availableUsers } = useUser();
  const otherUser = availableUsers.find(u => u.id === otherUserId);

  const [messages, setMessages] = useState<PrivateChatMessage[]>([]);
  const [input, setInput] = useState('');
  const messagesEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (otherUser) {
      setMessages(getPrivateChatMessages(currentUser.id, otherUser.id));
    }
  }, [currentUser.id, otherUser]);

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  // Simulate incoming messages from the other user
  useEffect(() => {
    if (!otherUser) return;

    const interval = setInterval(() => {
      // Only send if it's not the current user's turn
      const lastMessage = messages[messages.length - 1];
      if (!lastMessage || lastMessage.senderId === currentUser.id) {
        const aiComments = [
          "Hey, I just saw that amazing goal!",
          "What do you think about the latest transfer rumors?",
          "Can't believe that call by the ref!",
          "This season is wild, right?",
          "Who's your pick for MVP this year?",
          "Just finished watching the highlights, insane game!",
        ];
        const randomComment = aiComments[Math.floor(Math.random() * aiComments.length)];

        const aiMessage: PrivateChatMessage = {
          id: Date.now().toString() + Math.random().toString(36).substring(7),
          senderId: otherUser.id,
          receiverId: currentUser.id,
          text: randomComment,
          timestamp: new Date(),
        };
        addPrivateChatMessage(aiMessage);
        setMessages(prev => [...prev, aiMessage]);
      }
    }, 20000); // AI message every 20 seconds

    return () => clearInterval(interval);
  }, [messages, currentUser.id, otherUser]);


  const handleSendMessage = useCallback((e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || !otherUser) return;

    const newMessage: PrivateChatMessage = {
      id: Date.now().toString(), // Simple unique ID
      senderId: currentUser.id,
      receiverId: otherUser.id,
      text: input,
      timestamp: new Date(),
    };

    addPrivateChatMessage(newMessage);
    setMessages(prev => [...prev, newMessage]);
    setInput('');
  }, [input, currentUser.id, otherUser]);

  if (!otherUser) {
    return (
      <div className="p-4 bg-secondary rounded-lg shadow-xl text-center text-red-400">
        User not found to chat with.
      </div>
    );
  }

  return (
    <div className="p-4 bg-secondary rounded-lg shadow-xl h-[calc(100vh-180px)] flex flex-col">
      <div className="flex items-center border-b border-border pb-4 mb-4">
        <Link to="/chats" className="text-secondary hover:text-primary mr-3" aria-label="Back to chats list">
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M10 19l-7-7m0 0l7-7m-7 7h18" />
          </svg>
        </Link>
        <img
          src={`https://picsum.photos/40/40?random=${otherUser.id.charCodeAt(0)}`}
          alt={`${otherUser.name}'s avatar`}
          className="w-10 h-10 object-cover rounded-full border-2 border-border mr-3"
        />
        <h1 className="text-xl font-bold text-accent">{otherUser.name}</h1>
      </div>

      <div className="flex-grow overflow-y-auto custom-scrollbar p-2 mb-4 space-y-3 bg-tertiary rounded-lg">
        {messages.length === 0 ? (
          <p className="text-center text-secondary italic pt-4">No messages yet. Say hello to {otherUser.name}!</p>
        ) : (
          messages.map((msg) => {
            const isCurrentUser = msg.senderId === currentUser.id;
            const senderName = isCurrentUser ? 'You' : otherUser.name;
            const senderAvatar = `https://picsum.photos/20/20?random=${msg.senderId.charCodeAt(0)}`;

            return (
              <div key={msg.id} className={`flex items-start ${isCurrentUser ? 'justify-end' : 'justify-start'}`}>
                {!isCurrentUser && (
                  <img src={senderAvatar} alt={`${senderName}'s avatar`} className="w-6 h-6 object-cover rounded-full mr-2 flex-shrink-0 mt-1" />
                )}
                <div className={`max-w-[80%] p-2 rounded-lg shadow-sm ${isCurrentUser ? 'bg-accent text-primary' : 'bg-secondary text-primary'}`}>
                  <p className="font-semibold text-xs mb-1">{senderName}</p>
                  <p className="text-sm break-words">{msg.text}</p>
                  <span className="block text-right text-xs text-secondary mt-1">
                    {msg.timestamp.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
                {isCurrentUser && (
                  <img src={senderAvatar} alt={`${senderName}'s avatar`} className="w-6 h-6 object-cover rounded-full ml-2 flex-shrink-0 mt-1" />
                )}
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      <form onSubmit={handleSendMessage} className="flex space-x-2">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={`Message ${otherUser.name}...`}
          className="flex-grow bg-tertiary text-primary border border-border rounded-lg py-2 px-3 focus:outline-none focus:ring-1 focus:ring-accent"
          aria-label={`Message to ${otherUser.name}`}
        />
        <button
          type="submit"
          className="bg-accent hover:bg-emerald-700 text-primary p-2 rounded-lg transition-colors duration-200 disabled:opacity-50 disabled:cursor-not-allowed"
          disabled={!input.trim()}
          aria-label="Send message"
        >
          <svg xmlns="http://www.w3.org/2000/svg" className="h-6 w-6" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path strokeLinecap="round" strokeLinejoin="round" d="M14 5l7 7m0 0l-7 7m7-7H3" />
          </svg>
        </button>
      </form>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { HashRouter, Routes, Route, Link } from 'react-router-dom';
import { HomePage } from './pages/HomePage';
import { PlayerPage } from './pages/PlayerPage';
import { TeamPage } from './pages/TeamPage';
import { LeaguePage } from './pages/LeaguePage';
import { MyWatchlistPage } from './pages/MyWatchlistPage';
import { MyScoreboardPage } from './pages/MyScoreboardPage';
import { SearchPage } from './pages/SearchPage';
import { Header } from './components/Header';
import { Footer } from './components/Footer';
import { ChatBot } from './components/ChatBot';
import { Sidebar } from './components/Sidebar';
import { UserProvider } from './context/UserContext';

// New social pages
import { UserProfilePage } from './pages/UserProfilePage';
import { UserWatchlistPage } from './pages/UserWatchlistPage';
import { UserScoreboardPage } from './pages/UserScoreboardPage';
import { AllUsersPage } from './pages/AllUsersPage';
import { ChatsPage } from './pages/ChatsPage';
import { IndividualChatPage } from './pages/IndividualChatPage';
import { WatchPartyPage } from './pages/WatchPartyPage';

function App() {
  const [isChatBotOpen, setIsChatBotOpen] = useState(false);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [theme, setTheme] = useState<'dark' | 'light'>('dark');

  // Set initial theme from localStorage or default to dark
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    if (savedTheme === 'light') {
      setTheme('light');
      document.body.classList.add('light-theme');
    } else {
      setTheme('dark');
      document.body.classList.remove('light-theme');
    }
  }, []);

  const toggleChatBot = () => {
    setIsChatBotOpen(prev => !prev);
  };

  const toggleSidebar = () => {
    setIsSidebarOpen(prev => !prev);
  };

  const toggleTheme = () => {
    setTheme(prevTheme => {
      const newTheme = prevTheme === 'dark' ? 'light' : 'dark';
      if (newTheme === 'light') {
        document.body.classList.add('light-theme');
      } else {
        document.body.classList.remove('light-theme');
      }
      localStorage.setItem('theme', newTheme);
      return newTheme;
    });
  };

  return (
    <UserProvider>
      <HashRouter>
        <div className={`min-h-screen flex flex-col bg-primary text-primary`}>
          <Header
            toggleChatBot={toggleChatBot}
            toggleSidebar={toggleSidebar}
            toggleTheme={toggleTheme}
            currentTheme={theme}
          />
          <div className="flex flex-grow">
            <Sidebar isOpen={isSidebarOpen} onClose={toggleSidebar} />
            <main className="flex-grow container mx-auto p-4 sm:p-6 lg:p-4 transition-all duration-300 ease-in-out">
              <Routes>
                <Route path="/" element={<HomePage />} />
                <Route path="/player/:playerName" element={<PlayerPage />} />
                <Route path="/team/:teamName" element={<TeamPage />} />
                <Route path="/league/:leagueName" element={<LeaguePage />} />
                <Route path="/watchlist" element={<MyWatchlistPage />} />
                <Route path="/scoreboard" element={<MyScoreboardPage />} />
                <Route path="/search" element={<SearchPage />} />

                {/* New Social Routes */}
                <Route path="/users" element={<AllUsersPage />} />
                <Route path="/users/:userId" element={<UserProfilePage />} />
                <Route path="/users/:userId/watchlist" element={<UserWatchlistPage />} />
                <Route path="/users/:userId/scoreboard" element={<UserScoreboardPage />} />
                <Route path="/chats" element={<ChatsPage />} />
                <Route path="/chats/:otherUserId" element={<IndividualChatPage />} />
                <Route path="/game/:gameId/watchparty" element={<WatchPartyPage />} />

              </Routes>
            </main>
          </div>
          <Footer />
          <ChatBot isOpen={isChatBotOpen} onClose={() => setIsChatBotOpen(false)} />
        </div>
      </HashRouter>
    </UserProvider>
  );
}

export default App;

